use crate::common;
use rust_xlsxwriter::{DataValidation, DataValidationRule, Workbook, XlsxError};

// Create a rust_xlsxwriter file to compare against an Excel file.
fn create_new_xlsx_file(filename: &str) -> Result<(), XlsxError> {
    let mut workbook = Workbook::new();

    let worksheet = workbook.add_worksheet();

    let data_validation = DataValidation::new()
        .allow_whole_number(DataValidationRule::Between(1, 5))
        .set_input_title("a_x0041_b")?
        .set_input_message("a_x0041_b")?
        .set_error_title("a_x0041_b")?
        .set_error_message("a_x0041_b")?;

    worksheet.add_data_validation(0, 0, 0, 0, &data_validation)?;

    workbook.save(filename)?;

    Ok(())
}

#[test]
fn test_escapes13() {
    let test_runner = common::TestRunner::new()
        .set_name("escapes13")
        .set_function(create_new_xlsx_file)
        .initialize();

    test_runner.assert_eq();
    test_runner.cleanup();
}
